SELECT *
FROM sys_message
WHERE source_type = #{sourceType}
  AND source_id = #{sourceId}
  AND receiver_type = #{receiverType}
  AND is_deleted = 0
FOR UPDATE

mapper.update:
UPDATE sys_message
SET push_type = #{pushType},
    status = #{sentStatus},
    publish_time = #{publishTime},
    update_time = CURRENT_TIMESTAMP
WHERE id = #{id}
  AND status = #{expectedStatus}
  AND push_type = #{expectedPushType}
  AND publish_time <=> #{expectedPublishTime}
  AND is_deleted = 0
